PAGES={
 'tentang':{'title':'Belajar dengan tujuan. Melangkah dengan kesiapan.','eyebrow':'TENTANG KEIGO','intro':'LPK KEIGO INDONESIA BAGUS hadir di Ketanggungan, Brebes, untuk mempersiapkan sumber daya manusia melalui pelatihan bahasa Jepang, keterampilan, dan kedisiplinan.','blocks':[('Visi','Mewujudkan generasi muda yang terampil, bermental positif, kreatif, mandiri, dan mampu bersaing untuk pembangunan Indonesia.'),('Misi','Menyelenggarakan pelatihan bahasa Jepang; mendidik peserta untuk persiapan magang dan bekerja ke Jepang; meningkatkan kualitas SDM, kemandirian, kreativitas, serta taraf perekonomian.'),('Organisasi','Pimpinan: Haryanti. Penasihat: Selly Qodriyah S, S.S. Sekretaris: Hardi. Bendahara: Balda Aisah, S.P. Admin: N. Malika Z, S.Pi. Marketing: Fiko Aji Setiawan. Humas: Danu Setia Budi. Instruktur: H. Ina Zaenalfadli dan Moh. Djulidjantoro. Berdasarkan company profile 2026.'),('Legalitas','Company profile memuat dokumen perizinan usaha, pengesahan badan hukum, dan administrasi perusahaan. Hubungi pengelola untuk memeriksa dokumen dan ruang lingkup izin terbaru sebelum mengambil keputusan.')]},
 'program':{'title':'Persiapan yang terarah untuk langkah ke Jepang.','eyebrow':'PROGRAM PELATIHAN','intro':'Mulai dari bahasa, lanjutkan dengan pemahaman budaya dan kesiapan kerja. Pemilihan jalur dibantu oleh tim LPK.','blocks':[('Bahasa Jepang','Pembelajaran selama enam bulan sesuai company profile, meliputi bahasa Jepang, pengetahuan hidup dan kerja di Jepang, serta latihan fisik dan mental.'),('Kelas reguler','Senin–Jumat 07.30–15.00 WIB dan Sabtu 07.30–12.00 WIB.'),('Kelas karyawan','Malam Selasa–malam Sabtu, 20.00–22.00 WIB. Konfirmasikan ketersediaan kelas kepada pengelola.'),('Magang Jepang','Program pengembangan keterampilan melalui pengalaman kerja. LPK membantu persiapan dan proses seleksi. Syarat dan durasi mengikuti program serta ketentuan yang berlaku.'),('Tokutei Ginou (SSW)','Jalur kerja dengan keterampilan spesifik. Persiapan mencakup bahasa Jepang dan sertifikasi keterampilan sesuai bidang. Persyaratan akhir perlu dikonfirmasi sesuai lowongan.'),('Bidang peluang','Pengolahan makanan/minuman, kaigo, manufaktur, konstruksi, restoran, pertanian, perhotelan, building cleaning, perawatan mobil, pengelasan, peternakan, dan perikanan. Daftar bidang bukan jaminan ketersediaan lowongan.'),('Persyaratan awal','Company profile mencantumkan usia 18–35 tahun, lulusan SMA/SMK atau sederajat, dan persyaratan fisik/kesehatan. Persyaratan dapat berbeda menurut program dan lowongan; konsultasikan dengan admin. Tidak ada keputusan seleksi otomatis.'),('Dokumen persiapan','CV, KTP, Kartu Keluarga, akta kelahiran, ijazah SD hingga pendidikan terakhir, dokumen kesehatan, surat izin keluarga, dan pas foto. Rincian kebutuhan akan dikonfirmasi pengelola.')]},
 'fasilitas':{'title':'Ruang untuk belajar, bertumbuh, dan mempersiapkan diri.','eyebrow':'KEHIDUPAN DI KEIGO','intro':'Foto kegiatan dan fasilitas dari company profile Keigo.','blocks':[('Belajar & berlatih','Ruang kelas, layar presentasi, perangkat pembelajaran, dan jaringan internet mendukung kegiatan pelatihan.'),('Fasilitas pendukung','Area administrasi, ruang konsultasi, lobi, asrama, dapur bersama, mushola, P3K, serta halaman kegiatan. Ketersediaan dikonfirmasi saat pendaftaran.')]},
 'alur':{'title':'Setiap langkah, lebih jelas.','eyebrow':'ALUR PERSIAPAN','intro':'Urutan berikut mengikuti company profile Keigo. Proses dan hasil seleksi dikelola LPK bersama pihak terkait.','blocks':[('Pengajuan melalui LPK','Siswa memilih lowongan di portal. Admin LPK memeriksa CV dan memproses pengajuan eksternal; portal tidak mengirim langsung kepada perusahaan Jepang.')]},
 'kontak':{'title':'Mulai dengan percakapan.','eyebrow':'HUBUNGI KEIGO','intro':'Diskusikan program, jadwal belajar, dan dokumen persiapan dengan tim LPK.','blocks':[('Alamat',INSTITUTION['address']),('Telepon',INSTITUTION['phone']+' / '+INSTITUTION['phone_alt']),('Email',INSTITUTION['email'])]},
 'privasi':{'title':'Penggunaan data di portal Keigo','eyebrow':'PRIVASI DATA','intro':'CV dan dokumen hanya tersedia bagi pemilik akun dan admin yang berwenang.','blocks':[('Tujuan pengumpulan','Informasi digunakan untuk melengkapi profil calon peserta, memeriksa dokumen, dan memproses lowongan yang dipilih melalui LPK.'),('Akses dan koreksi','Anda dapat memperbarui draft CV dan meminta koreksi kepada admin. Versi yang sudah terkait pengajuan disimpan agar riwayat tetap akurat.'),('Dokumen dan retensi','Dokumen disimpan secara privat. Kebijakan jangka penyimpanan, penghapusan, dan dasar pemrosesan final harus disahkan pengelola sebelum penggunaan produksi.'),('Permintaan terkait data','Hubungi '+INSTITUTION['email']+' untuk permintaan akses, koreksi, atau penghapusan yang memerlukan pemeriksaan pengelola.')]}}
